            'group'       => 'branding',
            'default'     => 'UTC',
            'sensitive'   => false,
            'config_key'  => 'timezone',
            // Dynamic option list from PHP's zoneinfo database (~420 entries).
            // Callable form keeps the registry lazy — the list is only built
            // when settings.php actually renders or validates this field.
            'options'     => '@timezone',
